// 1. Get raw AI output string
const raw = $json.output;

// 2. Remove markdown ```json ``` wrappers
const clean = raw.replace(/```json|```/g, '').trim();

// 3. Parse JSON safely
const data = JSON.parse(clean);

// 4. Split recipients into separate items
return data.recipients.map(name => ({
  name,
  subject: data.subject,
  body: data.body || "Please confirm your availability."
}));
